var compressImage = (file, max = 900, q = 0.72) => new Promise((res, rej) => {
  if (!file || !file.type.startsWith("image/")) return rej(new Error("Choose an image file"));
  const r = new FileReader();
  r.onerror = () => rej(new Error("Could not read that image"));
  r.onload = () => {
    const img2 = new Image();
    img2.onerror = () => rej(new Error("Could not read that image"));
    img2.onload = () => {
      const k = Math.min(1, max / Math.max(img2.width, img2.height)), c = document.createElement("canvas");
      c.width = Math.round(img2.width * k);
      c.height = Math.round(img2.height * k);
      c.getContext("2d").drawImage(img2, 0, 0, c.width, c.height);
      res(c.toDataURL("image/jpeg", q));
    };
    img2.src = r.result;
  };
  r.readAsDataURL(file);
});

